-- Performance indexes + job analysis cache + atomic status update RPC

CREATE TABLE IF NOT EXISTS public.job_analysis_cache (
  job_hash text PRIMARY KEY,
  analysis jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE INDEX IF NOT EXISTS idx_resumes_user_id ON public.resumes(user_id);
CREATE INDEX IF NOT EXISTS idx_jobs_user_id ON public.jobs(user_id);
CREATE INDEX IF NOT EXISTS idx_jobs_user_id_active ON public.jobs(user_id, is_active) WHERE is_active = true;
CREATE INDEX IF NOT EXISTS idx_job_applications_user_id ON public.job_applications(user_id);
CREATE INDEX IF NOT EXISTS idx_job_applications_status ON public.job_applications(status);
CREATE INDEX IF NOT EXISTS idx_job_application_events_application_id
  ON public.job_application_events(application_id);

CREATE OR REPLACE FUNCTION public.update_application_status(
  app_id uuid,
  new_status text,
  user_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  prev_status text;
BEGIN
  IF new_status NOT IN ('saved', 'applied', 'interview', 'rejected', 'accepted') THEN
    RAISE EXCEPTION 'Invalid status';
  END IF;

  SELECT status INTO prev_status
  FROM public.job_applications
  WHERE id = app_id AND job_applications.user_id = user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Application not found';
  END IF;

  UPDATE public.job_applications
  SET status = new_status,
      updated_at = timezone('utc'::text, now())
  WHERE id = app_id AND user_id = user_id;

  IF prev_status IS DISTINCT FROM new_status THEN
    INSERT INTO public.job_application_events(application_id, from_status, to_status)
    VALUES (app_id, prev_status, new_status);
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.update_application_status(uuid, text, uuid) TO authenticated;

CREATE INDEX IF NOT EXISTS idx_courses_level ON public.courses(level);

ALTER TABLE public.job_analysis_cache ENABLE ROW LEVEL SECURITY;

CREATE POLICY job_analysis_cache_select_authenticated ON public.job_analysis_cache
  FOR SELECT TO authenticated USING (true);

CREATE POLICY job_analysis_cache_upsert_authenticated ON public.job_analysis_cache
  FOR ALL TO authenticated USING (true) WITH CHECK (true);

GRANT SELECT, INSERT, UPDATE ON TABLE public.job_analysis_cache TO authenticated;


-- ===== 20260530000000_admin_role.sql =====
-- Migration: Admin role management
-- Adds a secure server-side function to grant/revoke admin via app_metadata.
-- This cannot be called by regular users (SECURITY DEFINER + explicit caller check).

-- Function to grant admin role (call via service role only)
CREATE OR REPLACE FUNCTION public.set_admin_role(target_user_id uuid, grant_admin boolean)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Only allow service role or existing admins to call this
  IF (auth.jwt() ->> 'role') NOT IN ('service_role') THEN
    RAISE EXCEPTION 'Insufficient privileges';
  END IF;

  UPDATE auth.users
  SET raw_app_meta_data =
    CASE
      WHEN grant_admin THEN
        COALESCE(raw_app_meta_data, '{}'::jsonb) || '{"is_admin": true}'::jsonb
      ELSE
        COALESCE(raw_app_meta_data, '{}'::jsonb) - 'is_admin'
    END
  WHERE id = target_user_id;
END;
$$;

-- Seed admin from env if SEED_ADMIN_EMAIL matches an existing user
-- This runs on migration and is idempotent
DO $$
DECLARE
  v_admin_email text := current_setting('app.seed_admin_email', true);
  v_user_id uuid;
BEGIN
  IF v_admin_email IS NULL OR v_admin_email = '' OR v_admin_email = 'admin@admin.com' THEN
    -- Use the known seed email for local Docker setup only
    v_admin_email := 'admin@admin.com';
  END IF;

  SELECT id INTO v_user_id FROM auth.users WHERE email = lower(v_admin_email) LIMIT 1;

  IF v_user_id IS NOT NULL THEN
    UPDATE auth.users
    SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || '{"is_admin": true}'::jsonb
    WHERE id = v_user_id;
    RAISE NOTICE 'Admin role granted to %', v_admin_email;
  ELSE
    RAISE NOTICE 'Admin user % not found — skipping seed', v_admin_email;
  END IF;
END;
$$;


-- ===== 20260531000000_loyalty_points.sql =====
-- ============================================================
-- Loyalty Points System — Digimytch Talent Hub
-- ============================================================

-- 1. Add institution + is_digimytch columns to courses
ALTER TABLE public.courses
  ADD COLUMN IF NOT EXISTS institution text NULL,
  ADD COLUMN IF NOT EXISTS institution_logo_url text NULL,
  ADD COLUMN IF NOT EXISTS is_digimytch boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS loyalty_points_reward integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS duration_hours integer NULL,
  ADD COLUMN IF NOT EXISTS certificate boolean NOT NULL DEFAULT false;

-- 2. Loyalty points table
CREATE TABLE IF NOT EXISTS public.loyalty_points (
  id uuid NOT NULL DEFAULT uuid_generate_v4(),
  user_id uuid NOT NULL,
  points integer NOT NULL DEFAULT 0,
  total_earned integer NOT NULL DEFAULT 0,
  created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT loyalty_points_pkey PRIMARY KEY (id),
  CONSTRAINT loyalty_points_user_id_key UNIQUE (user_id),
  CONSTRAINT loyalty_points_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users (id) ON DELETE CASCADE
);

-- 3. Course completions (tracks which courses a user completed)
CREATE TABLE IF NOT EXISTS public.course_completions (
  id uuid NOT NULL DEFAULT uuid_generate_v4(),
  user_id uuid NOT NULL,
  course_id uuid NOT NULL,
  completed_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  points_earned integer NOT NULL DEFAULT 0,
  CONSTRAINT course_completions_pkey PRIMARY KEY (id),
  CONSTRAINT course_completions_user_course UNIQUE (user_id, course_id),
  CONSTRAINT course_completions_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users (id) ON DELETE CASCADE,
  CONSTRAINT course_completions_course_id_fkey FOREIGN KEY (course_id) REFERENCES public.courses (id) ON DELETE CASCADE
);

-- 4. RLS policies
ALTER TABLE public.loyalty_points ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.course_completions ENABLE ROW LEVEL SECURITY;

CREATE POLICY loyalty_points_own ON public.loyalty_points
  FOR ALL TO authenticated USING (auth.uid() = user_id);

CREATE POLICY course_completions_own ON public.course_completions
  FOR ALL TO authenticated USING (auth.uid() = user_id);

-- 5. Function to add points when a Digimytch course is completed
CREATE OR REPLACE FUNCTION public.complete_digimytch_course(p_course_id uuid)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_course record;
  v_already_completed boolean;
  v_new_points integer;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_course FROM courses WHERE id = p_course_id AND is_digimytch = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Course not found or not a Digimytch course';
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM course_completions WHERE user_id = v_user_id AND course_id = p_course_id
  ) INTO v_already_completed;

  IF v_already_completed THEN
    RETURN json_build_object('ok', false, 'error', 'Course already completed');
  END IF;

  INSERT INTO course_completions (user_id, course_id, points_earned)
  VALUES (v_user_id, p_course_id, v_course.loyalty_points_reward);

  INSERT INTO loyalty_points (user_id, points, total_earned)
  VALUES (v_user_id, v_course.loyalty_points_reward, v_course.loyalty_points_reward)
  ON CONFLICT (user_id) DO UPDATE
    SET points = loyalty_points.points + v_course.loyalty_points_reward,
        total_earned = loyalty_points.total_earned + v_course.loyalty_points_reward,
        updated_at = now();

  SELECT points INTO v_new_points FROM loyalty_points WHERE user_id = v_user_id;

  RETURN json_build_object(
    'ok', true,
    'points_earned', v_course.loyalty_points_reward,
    'total_points', v_new_points
  );
END;
$$;

-- 6. Update Digimytch courses seed data with institutions + loyalty points
UPDATE public.courses SET
  institution = 'Digimytch Academy',
  institution_logo_url = '/digimytch-logo.png',
  is_digimytch = true,
  loyalty_points_reward = 150,
  certificate = true
WHERE provider = 'Digimytch';

-- 7. Add institutions to known providers
UPDATE public.courses SET institution = 'Google', institution_logo_url = '/logos/google.png'
  WHERE provider ILIKE '%google%';
UPDATE public.courses SET institution = 'Meta', institution_logo_url = '/logos/meta.png'
