-- ===== 20260605120000_pgvector_semantic_matching.sql =====
-- Semantic job–resume matching via pgvector (1536-dim, cosine / HNSW)
-- Local Supabase Docker installe le type dans le schéma `storage`

ALTER TABLE public.jobs DROP COLUMN IF EXISTS embedding;
ALTER TABLE public.resumes DROP COLUMN IF EXISTS embedding;

ALTER TABLE public.jobs
  ADD COLUMN embedding vector(1536);

ALTER TABLE public.resumes
  ADD COLUMN embedding vector(1536);

DROP INDEX IF EXISTS idx_jobs_embedding_hnsw;
DROP INDEX IF EXISTS idx_resumes_embedding_hnsw;

CREATE INDEX idx_jobs_embedding_hnsw
  ON public.jobs
  USING hnsw (embedding vector_cosine_ops)
  WITH (m = 16, ef_construction = 64)
  WHERE embedding IS NOT NULL AND deleted_at IS NULL;

CREATE INDEX idx_resumes_embedding_hnsw
  ON public.resumes
  USING hnsw (embedding vector_cosine_ops)
  WITH (m = 16, ef_construction = 64)
  WHERE embedding IS NOT NULL AND deleted_at IS NULL;

CREATE OR REPLACE FUNCTION public.match_jobs_semantic(
  p_user_id uuid,
  p_resume_embedding vector(1536),
  p_match_threshold float DEFAULT 0.25,
  p_match_count int DEFAULT 40
)
RETURNS TABLE (
  job_id uuid,
  similarity float
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public, extensions
AS $$
  SELECT
    j.id AS job_id,
    (1 - (j.embedding <=> p_resume_embedding))::float AS similarity
  FROM public.jobs j
  WHERE j.user_id = p_user_id
    AND j.is_active = true
    AND j.deleted_at IS NULL
    AND j.embedding IS NOT NULL
    AND (1 - (j.embedding <=> p_resume_embedding)) >= p_match_threshold
  ORDER BY j.embedding <=> p_resume_embedding
  LIMIT GREATEST(p_match_count, 1);
$$;

CREATE OR REPLACE FUNCTION public.job_resume_semantic_similarity(
  p_job_id uuid,
  p_resume_id uuid
)
RETURNS float
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public, extensions
AS $$
  SELECT CASE
    WHEN j.embedding IS NULL OR r.embedding IS NULL THEN NULL
    ELSE (1 - (j.embedding <=> r.embedding))::float
  END
  FROM public.jobs j
  INNER JOIN public.resumes r ON r.id = p_resume_id AND r.user_id = j.user_id
  WHERE j.id = p_job_id
    AND j.deleted_at IS NULL
    AND r.deleted_at IS NULL;
$$;

GRANT EXECUTE ON FUNCTION public.match_jobs_semantic(uuid, vector, float, int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.job_resume_semantic_similarity(uuid, uuid) TO authenticated;


-- ===== 20260607120000_supabase_linter_performance_fixes.sql =====
-- Supabase database linter: auth RLS initplan, duplicate indexes, overlapping policies.

-- 1. Auth RLS initplan: evaluate auth.uid() once per query, not per row.
DROP POLICY IF EXISTS subscriptions_policy ON public.subscriptions;
CREATE POLICY subscriptions_policy ON public.subscriptions
  USING ((SELECT auth.uid()) = user_id)
  WITH CHECK ((SELECT auth.uid()) = user_id);

DROP POLICY IF EXISTS profiles_policy ON public.profiles;
CREATE POLICY profiles_policy ON public.profiles
  USING ((SELECT auth.uid()) = user_id)
  WITH CHECK ((SELECT auth.uid()) = user_id);

DROP POLICY IF EXISTS job_application_events_select_own ON public.job_application_events;
CREATE POLICY job_application_events_select_own ON public.job_application_events
  FOR SELECT TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.job_applications ja
      WHERE ja.id = job_application_events.application_id
        AND ja.user_id = (SELECT auth.uid())
    )
  );

DROP POLICY IF EXISTS job_application_events_insert_own ON public.job_application_events;
CREATE POLICY job_application_events_insert_own ON public.job_application_events
  FOR INSERT TO authenticated
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.job_applications ja
      WHERE ja.id = job_application_events.application_id
        AND ja.user_id = (SELECT auth.uid())
    )
  );

DROP POLICY IF EXISTS candidate_feedback_insert_own ON public.candidate_feedback;
CREATE POLICY candidate_feedback_insert_own ON public.candidate_feedback
  FOR INSERT TO authenticated
  WITH CHECK ((SELECT auth.uid()) = user_id);

DROP POLICY IF EXISTS candidate_feedback_select_own ON public.candidate_feedback;
CREATE POLICY candidate_feedback_select_own ON public.candidate_feedback
  FOR SELECT TO authenticated
  USING ((SELECT auth.uid()) = user_id);

DROP POLICY IF EXISTS loyalty_points_own ON public.loyalty_points;
CREATE POLICY loyalty_points_own ON public.loyalty_points
  FOR ALL TO authenticated
  USING ((SELECT auth.uid()) = user_id)
  WITH CHECK ((SELECT auth.uid()) = user_id);

DROP POLICY IF EXISTS course_completions_own ON public.course_completions;
CREATE POLICY course_completions_own ON public.course_completions
  FOR ALL TO authenticated
  USING ((SELECT auth.uid()) = user_id)
  WITH CHECK ((SELECT auth.uid()) = user_id);

-- 2. Multiple permissive SELECT policies on job_analysis_cache (FOR ALL already covers SELECT).
DROP POLICY IF EXISTS job_analysis_cache_select_authenticated ON public.job_analysis_cache;

-- 3. Duplicate indexes (keep idx_* names from perf migration).
DROP INDEX IF EXISTS public.job_application_events_application_id_idx;
DROP INDEX IF EXISTS public.job_applications_user_id_idx;


-- ===== 20260607130000_supabase_linter_remaining_fixes.sql =====
-- Supabase database linter: remaining security/performance fixes.

-- 1. Function search_path (SECURITY: function_search_path_mutable).
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

-- 2. Unindexed foreign keys on public tables (PERFORMANCE: unindexed_foreign_keys).
CREATE INDEX IF NOT EXISTS idx_candidate_feedback_admin_replied_by
  ON public.candidate_feedback (admin_replied_by);

CREATE INDEX IF NOT EXISTS idx_course_completions_course_id
  ON public.course_completions (course_id);

CREATE INDEX IF NOT EXISTS idx_job_applications_resume_id
  ON public.job_applications (resume_id);

CREATE INDEX IF NOT EXISTS idx_resumes_job_id
  ON public.resumes (job_id);

-- 3. RLS enabled without policies on service-role-only tables (SECURITY: rls_enabled_no_policy).
-- Client roles are revoked; explicit deny documents intent and satisfies the linter.
CREATE POLICY ai_usage_events_deny_clients ON public.ai_usage_events
  FOR ALL TO authenticated, anon
  USING (false)
  WITH CHECK (false);

CREATE POLICY stripe_webhook_events_deny_clients ON public.stripe_webhook_events
  FOR ALL TO authenticated, anon
  USING (false)
  WITH CHECK (false);


-- ===== 20260607140000_fix_update_application_status_auth.sql =====
-- Bind SECURITY DEFINER RPC to the authenticated caller (prevents user_id spoofing).

CREATE OR REPLACE FUNCTION public.update_application_status(
  app_id uuid,
  new_status text,
  user_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  prev_status text;
  p_user_id uuid := auth.uid();
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF user_id IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  IF new_status NOT IN ('saved', 'applied', 'interview', 'rejected', 'accepted') THEN
    RAISE EXCEPTION 'Invalid status';
  END IF;

  SELECT ja.status INTO prev_status
  FROM public.job_applications ja
  WHERE ja.id = app_id AND ja.user_id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Application not found';
  END IF;

  UPDATE public.job_applications ja
  SET status = new_status,
      updated_at = timezone('utc'::text, now())
  WHERE ja.id = app_id AND ja.user_id = p_user_id;

  IF prev_status IS DISTINCT FROM new_status THEN
    INSERT INTO public.job_application_events(application_id, from_status, to_status)
    VALUES (app_id, prev_status, new_status);
  END IF;
END;
$$;


-- ===== 20260607150000_rls_soft_delete_insert_hardening.sql =====
-- Require deleted_at IS NULL on INSERT; keep SELECT/UPDATE/DELETE for trash restore/purge.

DROP POLICY IF EXISTS resumes_policy ON public.resumes;
CREATE POLICY resumes_select_own ON public.resumes
  FOR SELECT TO authenticated
  USING ((SELECT auth.uid()) = user_id);
CREATE POLICY resumes_insert_own ON public.resumes
  FOR INSERT TO authenticated
  WITH CHECK ((SELECT auth.uid()) = user_id AND deleted_at IS NULL);
CREATE POLICY resumes_update_own ON public.resumes
  FOR UPDATE TO authenticated
  USING ((SELECT auth.uid()) = user_id)
  WITH CHECK ((SELECT auth.uid()) = user_id);
CREATE POLICY resumes_delete_own ON public.resumes
  FOR DELETE TO authenticated
  USING ((SELECT auth.uid()) = user_id);

DROP POLICY IF EXISTS jobs_policy ON public.jobs;
CREATE POLICY jobs_select_own ON public.jobs
  FOR SELECT TO authenticated
  USING ((SELECT auth.uid()) = user_id);
CREATE POLICY jobs_insert_own ON public.jobs
  FOR INSERT TO authenticated
  WITH CHECK ((SELECT auth.uid()) = user_id AND deleted_at IS NULL);
CREATE POLICY jobs_update_own ON public.jobs
  FOR UPDATE TO authenticated
  USING ((SELECT auth.uid()) = user_id)
  WITH CHECK ((SELECT auth.uid()) = user_id);
CREATE POLICY jobs_delete_own ON public.jobs
  FOR DELETE TO authenticated
  USING ((SELECT auth.uid()) = user_id);

DROP POLICY IF EXISTS job_applications_insert_own ON public.job_applications;
CREATE POLICY job_applications_insert_own ON public.job_applications
  FOR INSERT TO authenticated
  WITH CHECK ((SELECT auth.uid()) = user_id AND deleted_at IS NULL);


